import XCTest
@testable import AmbulandoCore

/// New-identity creation, encrypted (NIP-49) backup, restore and the payment gate. Every key here is generated by the test or is the
/// public NIP-19 test key; no real identity is touched. `logN: 10` keeps the debug-build scrypt cost small; the cost bounds and
/// default are covered in `NIP49Tests`.
final class IdentityBackupTests: XCTestCase {
    private let password = "correct horse battery staple"
    private let cheap: UInt8 = 10

    private func service(_ directory: URL = temporaryDirectory(), secrets: VaultSecretStore = MemorySecretStore()) -> (IdentityService, URL) {
        (IdentityService(vaultURL: directory.appendingPathComponent("vault.json"), secrets: secrets), directory)
    }

    /// Runs the whole creation flow up to, not including, `commit`.
    @discardableResult private func prepare(_ identity: IdentityService) async throws -> (npub: String, backup: String) {
        let preview = try await identity.beginNewIdentity()
        let backup = try await identity.createPendingBackup(password: password, logN: cheap)
        try await identity.notePendingBackupExported()
        try await identity.acknowledgePendingBackup(password: password)
        return (preview.npub, backup)
    }

    private func files(_ directory: URL) -> [URL] {
        (FileManager.default.enumerator(at: directory, includingPropertiesForKeys: nil)?.allObjects as? [URL] ?? []).filter { !$0.hasDirectoryPath }
    }

    // MARK: Creation

    func testCreatedIdentityIsUsableAndItsBackupRestoresTheSameKey() async throws {
        let (identity, directory) = service()
        let (npub, backup) = try await prepare(identity)
        let committed = try await identity.commitNewIdentity(pin: TestKeys.pin)
        XCTAssertEqual(committed, .unlocked(npub: npub))

        let template = NostrEventTemplate(kind: 1, tags: [], content: "synthetic", createdAt: 1_760_000_000)
        let signed = try await identity.sign(template)
        XCTAssertTrue(SignatureVerifier.verify(signed))
        XCTAssertEqual(NostrKeys.npub(publicKeyHex: signed.pubkey), npub)

        // The plaintext key is on disk nowhere: not as hex, not as an nsec, not the ncryptsec either.
        let opened = try NIP49.open(backup, password: password)
        let secretHex = opened.secretKey.hex, nsec = Bech32.encode(hrp: "nsec", data: opened.secretKey)
        for file in files(directory) {
            let text = String(decoding: try Data(contentsOf: file), as: UTF8.self)
            XCTAssertFalse(text.contains(secretHex), file.lastPathComponent)
            XCTAssertFalse(text.contains(nsec), file.lastPathComponent)
            XCTAssertFalse(text.contains(backup), file.lastPathComponent)
        }
        XCTAssertEqual(opened.keySecurity, .safe)

        // Restore on a different "device": same npub, same signatures.
        let (restored, _) = service()
        let restoredState = try await restored.importBackup(ncryptsec: backup, password: password, pin: "1357")
        XCTAssertEqual(restoredState, .unlocked(npub: npub))
        let again = try await restored.sign(template)
        XCTAssertEqual(again.pubkey, signed.pubkey)
        XCTAssertTrue(SignatureVerifier.verify(again))
        let restoredGate = await restored.paymentBackupGate()
        XCTAssertEqual(restoredGate, .allowed, "an imported identity is never forced through the new-identity gate")
    }

    func testEachNewIdentityIsDifferentAndValid() async throws {
        let (identity, _) = service()
        let first = try await identity.beginNewIdentity().npub
        let second = try await identity.beginNewIdentity().npub
        XCTAssertNotEqual(first, second)
        XCTAssertTrue(NostrKeys.isValidNpub(first))
        for _ in 0..<20 { XCTAssertTrue(NostrKeys.isValidScalar(try NewIdentity.generateSecret())) }
    }

    func testCommitNeedsExportedAcknowledgedBackup() async throws {
        let (identity, directory) = service()
        _ = try await identity.beginNewIdentity()
        func refused(_ label: String) async {
            do { _ = try await identity.commitNewIdentity(pin: TestKeys.pin); XCTFail("committed: \(label)") }
            catch { XCTAssertEqual(error as? IdentityError, .missing, label) }
        }
        await refused("no backup at all")
        _ = try await identity.createPendingBackup(password: password, logN: cheap)
        await refused("backup made but never exported")
        do { try await identity.acknowledgePendingBackup(password: password); XCTFail("acknowledged before export") }
        catch { XCTAssertEqual(error as? IdentityError, .missing) }
        try await identity.notePendingBackupExported()
        await refused("exported but not acknowledged")
        do { try await identity.acknowledgePendingBackup(password: "not the password"); XCTFail("acknowledged with wrong password") }
        catch { XCTAssertEqual(error as? NIP49Error, .wrongPasswordOrDamaged) }
        await refused("wrong confirmation password")
        let existsAfterRefusals = await identity.state
        XCTAssertEqual(existsAfterRefusals, .none)
        XCTAssertTrue(files(directory).isEmpty, "nothing is written before the backup is confirmed")
        // A new backup (new password) invalidates the earlier acknowledgement.
        try await identity.acknowledgePendingBackup(password: password)
        _ = try await identity.createPendingBackup(password: "another password", logN: cheap)
        await refused("backup replaced after acknowledgement")
    }

    func testRecordPersistenceFailureKeepsPendingKeyAndStartsNothing() async throws {
        let (identity, directory) = service()
        let (npub, _) = try await prepare(identity)
        // A directory where the record file must go makes the write fail.
        let blocker = directory.appendingPathComponent("identity-backup.json")
        try FileManager.default.createDirectory(at: blocker, withIntermediateDirectories: true)
        do { _ = try await identity.commitNewIdentity(pin: TestKeys.pin); XCTFail("committed without a record") } catch {}
        let afterFailure = await identity.state
        XCTAssertEqual(afterFailure, .none)
        XCTAssertFalse(FileManager.default.fileExists(atPath: directory.appendingPathComponent("vault.json").path))
        let stillPending = await identity.hasPendingNewIdentity
        XCTAssertTrue(stillPending)
        try FileManager.default.removeItem(at: blocker)
        let committed = try await identity.commitNewIdentity(pin: TestKeys.pin)
        XCTAssertEqual(committed, .unlocked(npub: npub), "the same key is committed on retry")
    }

    func testVaultFailureRemovesTheRecordAndKeepsThePendingKey() async throws {
        let (identity, directory) = service(secrets: UnavailableSecretStore())
        try await prepare(identity)
        do { _ = try await identity.commitNewIdentity(pin: TestKeys.pin); XCTFail("vault should have failed") } catch {}
        let state = await identity.state
        XCTAssertEqual(state, .none)
        XCTAssertFalse(FileManager.default.fileExists(atPath: directory.appendingPathComponent("identity-backup.json").path), "no record without a vault")
        let pending = await identity.hasPendingNewIdentity
        XCTAssertTrue(pending)
        let gate = await identity.paymentBackupGate()
        XCTAssertEqual(gate, .allowed, "no identity, nothing to gate")
    }

    func testCreationNeverReplacesOrSwitchesAnExistingIdentity() async throws {
        let identity = try await makeIdentity()
        do { _ = try await identity.beginNewIdentity(); XCTFail("began beside an existing vault") }
        catch { XCTAssertEqual(error as? IdentityError, .exists) }
        // A pending key made before another identity appeared cannot be committed over it, and an existing connection refuses it.
        let (other, _) = service()
        try await prepare(other)
        do { _ = try await other.commitNewIdentity(pin: TestKeys.pin, requiredNpub: TestKeys.npub); XCTFail("created while a connection exists") }
        catch { XCTAssertEqual(error as? IdentityError, .accountMismatch) }
        let untouched = await identity.state
        XCTAssertEqual(untouched, .unlocked(npub: TestKeys.npub))
        let otherState = await other.state
        XCTAssertEqual(otherState, .none)
        do { _ = try await identity.importBackup(ncryptsec: try NIP49.seal(secretKey: Data(repeating: 7, count: 32), password: password, logN: cheap), password: password, pin: "1357"); XCTFail() }
        catch { XCTAssertEqual(error as? IdentityError, .exists) }
        let stillSame = await identity.state
        XCTAssertEqual(stillSame, .unlocked(npub: TestKeys.npub))
    }

    func testDiscardForgetsThePendingKey() async throws {
        let (identity, _) = service()
        try await prepare(identity)
        await identity.discardNewIdentity()
        let pending = await identity.hasPendingNewIdentity
        XCTAssertFalse(pending)
        do { _ = try await identity.commitNewIdentity(pin: TestKeys.pin); XCTFail() } catch { XCTAssertEqual(error as? IdentityError, .missing) }
    }

    // MARK: Import and export

    func testImportRefusesWrongPasswordTamperedAndMalformedBackupsWithoutCreatingAnything() async throws {
        let backup = try NIP49.seal(secretKey: Data(repeating: 9, count: 32), password: password, logN: cheap)
        var tampered = Array(backup)
        tampered[60] = tampered[60] == "q" ? "p" : "q"
        for (label, text, pw) in [("wrong password", backup, "nope"), ("tampered", String(tampered), password), ("not a backup", TestKeys.nsec, password)] {
            let (identity, directory) = service()
            do { _ = try await identity.importBackup(ncryptsec: text, password: pw, pin: TestKeys.pin); XCTFail(label) } catch {}
            let state = await identity.state
            XCTAssertEqual(state, .none, label)
            XCTAssertTrue(files(directory).isEmpty, label)
        }
        // Whitespace around a pasted backup is tolerated.
        let (identity, _) = service()
        let state = try await identity.importBackup(ncryptsec: "  \(backup)\n", password: password, pin: TestKeys.pin)
        XCTAssertEqual(state.npub, try NewIdentity.npub(secret: Data(repeating: 9, count: 32)))
    }

    func testImportHonoursAnExistingConnectionIdentity() async throws {
        let (identity, _) = service()
        let backup = try NIP49.seal(secretKey: Data(repeating: 9, count: 32), password: password, logN: cheap)
        do { _ = try await identity.importBackup(ncryptsec: backup, password: password, pin: TestKeys.pin, requiredNpub: TestKeys.npub); XCTFail() }
        catch { XCTAssertEqual(error as? IdentityError, .accountMismatch) }
        let state = await identity.state
        XCTAssertEqual(state, .none)
    }

    func testExportBackupNeedsUnlockAndMarksSecurityHonestly() async throws {
        let imported = try await makeIdentity()
        let importedBackup = try await imported.exportBackup(password: password, logN: cheap)
        let opened = try NIP49.open(importedBackup, password: password)
        XCTAssertEqual(opened.secretKey.hex, TestKeys.secretHex)
        XCTAssertEqual(opened.keySecurity, .untracked, "an imported key's history is unknown")
        await imported.lock()
        do { _ = try await imported.exportBackup(password: password, logN: cheap); XCTFail("exported while locked") }
        catch { XCTAssertEqual(error as? IdentityError, .locked) }

        let (created, _) = service()
        try await prepare(created)
        _ = try await created.commitNewIdentity(pin: TestKeys.pin)
        let createdBackup = try await created.exportBackup(password: "different", logN: cheap)
        XCTAssertEqual(try NIP49.open(createdBackup, password: "different").keySecurity, .safe)
    }

    // MARK: Payment gate

    func testGateFollowsTheRecord() async throws {
        let (identity, directory) = service()
        let plain = await identity.paymentBackupGate()
        XCTAssertEqual(plain, .allowed, "no identity")
        try await prepare(identity)
        _ = try await identity.commitNewIdentity(pin: TestKeys.pin)
        let created = await identity.paymentBackupGate()
        XCTAssertEqual(created, .hostedBackupRequired, "local backup alone never satisfies the hosted requirement")
        XCTAssertTrue(HostedBackup.requirementNotice.contains("does not replace it"))

        let store = IdentityBackupStore(url: directory.appendingPathComponent("identity-backup.json"))
        let npub = await identity.state.npub!
        try store.save(IdentityBackupRecord(npub: npub, origin: .created))
        let unconfirmed = await identity.paymentBackupGate()
        XCTAssertEqual(unconfirmed, .localBackupRequired)
        try store.save(IdentityBackupRecord(npub: npub, origin: .created, localBackupConfirmedAt: Date(), hostedBackupConfirmedAt: Date()))
        let both = await identity.paymentBackupGate()
        XCTAssertEqual(both, .allowed)
        try Data("{broken".utf8).write(to: store.url)
        let broken = await identity.paymentBackupGate()
        XCTAssertEqual(broken, .localBackupRequired, "an unreadable record fails closed")
    }

    func testRemovingTheIdentityRemovesItsRecord() async throws {
        let (identity, directory) = service()
        try await prepare(identity)
        _ = try await identity.commitNewIdentity(pin: TestKeys.pin)
        XCTAssertTrue(FileManager.default.fileExists(atPath: directory.appendingPathComponent("identity-backup.json").path))
        _ = try await identity.remove()
        XCTAssertFalse(FileManager.default.fileExists(atPath: directory.appendingPathComponent("identity-backup.json").path))
    }

    // MARK: Onboarding controller

    private func gatedController(_ tower: FakeOnboardingTower, gate: PaymentBackupGate, store: OnboardingDraftStore) async throws -> OnboardingController {
        let signer = try await makeIdentity()
        let npub = NostrKeys.npub(publicKeyHex: try await signer.publicKeyHex())!
        return OnboardingController(origin: try TowerOrigin(tower.origin), signerNpub: npub, signer: signer, transport: tower, store: store,
                                    returnURL: OnboardingFixture.returnURL, backupGate: { gate }, makeKey: OnboardingFixture.keys())
    }

    func testPaymentIsRefusedBeforeAnySideEffectUntilBackupsAreComplete() async throws {
        for (gate, kind) in [(PaymentBackupGate.localBackupRequired, OnboardingFailure.Kind.backupRequired),
                             (.hostedBackupRequired, .hostedBackupRequired)] {
            let tower = FakeOnboardingTower()
            tower.inviteCodes[OnboardingFixture.invite] = 21
            let store = MemoryOnboardingDraftStore()
            let controller = try await gatedController(tower, gate: gate, store: store)
            let loaded = await controller.load()
            XCTAssertEqual(loaded.backupGate, gate)
            _ = await controller.edit(name: "Studio", fundingCents: 2100, agentOfferId: .some(nil), invite: OnboardingInviteCode(OnboardingFixture.invite))
            _ = await controller.confirmReview()
            let before = tower.requests.count
            let after = await controller.continueToPayment()
            XCTAssertEqual(after.failure?.kind, kind)
            XCTAssertNil(after.checkoutURL)
            XCTAssertNil(after.draft.intentId)
            XCTAssertEqual(tower.requests.count, before, "no account, create, options or checkout request")
            XCTAssertEqual(tower.count("POST", suffix: "/intents"), 0)
            XCTAssertEqual(tower.count("POST", suffix: "/checkout"), 0)
        }
    }

    func testAllowedGateStillPays() async throws {
        let tower = FakeOnboardingTower()
        tower.inviteCodes[OnboardingFixture.invite] = 21
        let controller = try await gatedController(tower, gate: .allowed, store: MemoryOnboardingDraftStore())
        _ = await controller.load()
        _ = await controller.edit(name: "Studio", fundingCents: 2100, agentOfferId: .some(nil), invite: OnboardingInviteCode(OnboardingFixture.invite))
        _ = await controller.confirmReview()
        let paid = await controller.continueToPayment()
        XCTAssertNotNil(paid.checkoutURL)
        XCTAssertEqual(tower.count("POST", suffix: "/checkout"), 1)
    }

    func testRequiredCopyExplainsHostedBackupBeforePayment() {
        let text = OnboardingFailure(kind: .hostedBackupRequired).errorDescription ?? ""
        XCTAssertTrue(text.contains("username"))
        XCTAssertTrue(text.contains("saved file or your PIN does not replace it"))
        XCTAssertTrue(text.contains("saved and checked"))
    }
}
